<?php namespace App\Policies; use App\Models\{User,HealthRecord}; class HealthRecordPolicy { public function view(User $u,HealthRecord $r):bool{return $u->role==='admin'||$r->pet->owner_id===$u->id||($u->role==='vet'&&$r->pet->appointments()->whereHas('vet',fn($q)=>$q->where('user_id',$u->id))->exists());} public function create(User $u):bool{return in_array($u->role,['owner','vet','admin'],true);} public function update(User $u,HealthRecord $r):bool{return $u->role==='admin'||$r->pet->owner_id===$u->id||$u->role==='vet';} public function delete(User $u,HealthRecord $r):bool{return $u->role==='admin'||$r->pet->owner_id===$u->id;} }